class EmployeeProfileScreen extends StatefulWidget{const EmployeeProfileScreen({super.key,required this.session,required this.employeeId});final SessionController session;final int employeeId;@override State<EmployeeProfileScreen> createState()=>_EmployeeProfileScreenState();}
class _EmployeeProfileScreenState extends State<EmployeeProfileScreen>{Map<String,dynamic>? employee;List<dynamic> attendance=[];String? error;@override void initState(){super.initState();load();}Future<void> load()async{try{final d=await widget.session.employee(widget.employeeId);if(mounted)setState((){employee=d['employee'] as Map<String,dynamic>?;attendance=d['attendance'] as List<dynamic>? ?? [];});}on ApiException catch(e){if(mounted)setState(()=>error=e.message);}}
Future<void> showAttendance() => showModalBottomSheet(context: context, builder: (context) => SafeArea(child: ListView(padding: const EdgeInsets.all(20), children: [const Text('Attendance history', style: TextStyle(fontSize:20,fontWeight:FontWeight.w800)), const SizedBox(height:12), if(attendance.isEmpty) const Text('No attendance records') else for(final item in attendance) ListTile(leading: const Icon(Icons.calendar_month,color:HRMateTheme.blue), title: Text('${item['attendance_date']} · ${item['status']}'), subtitle: Text('In: ${item['punch_in_at'] ?? '—'}   Out: ${item['punch_out_at'] ?? '—'}'))])));@override Widget build(BuildContext context){final e=employee;return Scaffold(backgroundColor:const Color(0xFFF5F8FC),appBar:AppBar(backgroundColor:const Color(0xFFF5F8FC),title:const Text('Employee profile')),body:e==null?Center(child:error==null?const CircularProgressIndicator():Text(error!)):ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[HRMateTheme.blue,HRMateTheme.green]),borderRadius:BorderRadius.circular(23)),child:Column(children:[const CircleAvatar(radius:34,backgroundColor:Colors.white,child:Icon(Icons.person,color:HRMateTheme.blue,size:40)),const SizedBox(height:10),Text(e['name']??'',style:const TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.w900)),Chip(label:Text(e['employee_code']??'',style:const TextStyle(fontSize:11))),Text('${e['department']??''} · ${e['shift_name']??''}',style:const TextStyle(color:Colors.white70)),const SizedBox(height:8),const Text('● Active',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w700))])),const SizedBox(height:20),_row(Icons.phone,e['phone']??'—','Phone'),_row(Icons.calendar_today,e['join_date']??'—','Joined'),_row(Icons.business,e['department']??'—','Department'),const SizedBox(height:24),Row(children:[Expanded(child:OutlinedButton(onPressed:showAttendance,child:const Text('View attendance'))),const SizedBox(width:10),Expanded(child:FilledButton(style:FilledButton.styleFrom(backgroundColor:HRMateTheme.blue),onPressed:()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>ManualAttendanceScreen(session:widget.session))),child:const Text('Add manual entry')))])]));}Widget _row(IconData i,String v,String l)=>Card(child:ListTile(leading:Icon(i,color:HRMateTheme.blue),title:Text(l),subtitle:Text(v)));}
